+        return;
+    }
+    showToast(trim(creatorName_) + " has moved into town!");
+    creatorName_.clear();
+    creatorBackstory_.clear();
+    creatorTraits_.clear();
+    creatorSeed_ = creatorSeed_ * 7919u + 13u;
+    draftLook_ = randomizeLook(creatorSeed_);
+}
