+        category == PartCategory::Body ? "any" : (body ? body->styleTag : "any");
+    const auto options = partsForCategory(category, gate);
+    if (options.empty()) return;
+
+    std::size_t index = 0;
+    for (std::size_t i = 0; i < options.size(); ++i) {
