87	// Unit forward vector on the ground plane for a yaw in degrees.
88	Vec3 flatForward(float yawDeg) {
89	    return normalize(Vec3{std::sin(degToRad(yawDeg)), 0.f, std::cos(degToRad(yawDeg))});
90	}
