872	                         world.npcs()[static_cast<std::size_t>(netNpc.npcIndex)].persona().name,
873	                         WHITE);
874	            }
875	        } else {
876	            for (const Npc& npc : world.npcs()) {
877	                plateFor(npc.position(), npc.persona().name, WHITE);
878	            }
879	        }
880	        for (const auto& remote : remotePlayers) {
881	            plateFor(remote.position, remote.name, Color{150, 220, 255, 255});
882	        }
883	
884	        // Combat callouts float above their NPC like temporary nameplates.
885	        for (const auto& callout : callouts) {
886	            if (callout.npcIndex < 0 ||
887	                callout.npcIndex >= static_cast<int>(world.npcs().size())) continue;
888	            const Npc& npc = world.npcs()[static_cast<std::size_t>(callout.npcIndex)];
889	            Vector2 screen;
890	            if (renderer.worldToScreen(npc.position() + Vec3{0.f, 2.6f, 0.f}, screen)) {
891	                drawNameplate(callout.text, screen, Color{255, 200, 120, 255});
892	            }
893	        }
894	
895	        if (mode == AppMode::Playing) {
896	            if (nearbyNpc >= 0 && nearbyNpc < static_cast<int>(world.npcs().size())) {
897	                const Npc& npc = world.npcs()[static_cast<std::size_t>(nearbyNpc)];
898	                drawCenteredHudText(
899	                    "[" + bindings.key(Action::Talk) + "] Talk to " + npc.persona().name, 20,
900	                    static_cast<float>(GetScreenHeight()) - 84.f);
901	            }
902	            if (jailSecondsLeft > 0.f) {
903	                const int secs = static_cast<int>(jailSecondsLeft) + 1;
904	                drawCenteredHudText("Arrested: disturbing the peace. Released in " +
905	                                        std::to_string(secs) + "s",
906	                                    22, static_cast<float>(GetScreenHeight()) - 120.f);
907	            }
908	            DrawCircle(GetScreenWidth() / 2, GetScreenHeight() / 2, 2.f,
909	                       Color{255, 255, 255, 200});
910	            // Weapon + health HUD (bottom-left), solo/host only.
911	            if (!joined) {
912	                const Player& p = world.player();
913	                const WeaponDef& def = weaponDef(p.weapon);
914	                std::string weaponLine = std::string("[1/2] ") + def.name;
915	                if (def.ammoMax > 0) {
916	                    const auto it = p.ammo.find(static_cast<std::uint8_t>(p.weapon));
917	                    weaponLine += "  ammo " +
918	                                  std::to_string(it != p.ammo.end() ? it->second : 0);
919	                }
920	                DrawText(weaponLine.c_str(), 24, GetScreenHeight() - 64, 18, RAYWHITE);
921	                DrawRectangle(24, GetScreenHeight() - 40, 180, 14, Color{40, 20, 20, 220});
922	                DrawRectangle(24, GetScreenHeight() - 40,
923	                              static_cast<int>(180.f * static_cast<float>(p.hp) /
924	                                               static_cast<float>(p.hpMax)),
925	                              14, Color{200, 60, 60, 255});
926	            }
927	        } else if (mode == AppMode::Dead) {
928	            DrawRectangle(0, 0, GetScreenWidth(), GetScreenHeight(), Color{40, 8, 8, 200});
929	            const char* headline = "You died.";
930	            DrawText(headline, (GetScreenWidth() - MeasureText(headline, 44)) / 2,
931	                     GetScreenHeight() / 2 - 48, 44, RAYWHITE);
932	            const char* hint = "Press Enter to wake up at the plaza.";
933	            DrawText(hint, (GetScreenWidth() - MeasureText(hint, 20)) / 2,
934	                     GetScreenHeight() / 2 + 12, 20, Color{220, 200, 200, 255});
935	        } else if (mode == AppMode::Dialogue) {
936	            DrawRectangle(0, 0, GetScreenWidth(), GetScreenHeight(), Color{8, 10, 16, 150});
937	            dialog.render();
938	        } else {
939	            menu.render();
940	        }
941	
942	        if (hurtFlash > 0.f) {
943	            const auto alpha = static_cast<unsigned char>(180.f * (hurtFlash / 0.35f));
944	            DrawRectangle(0, 0, GetScreenWidth(), GetScreenHeight(),
945	                          Color{200, 30, 30, alpha});
946	        }
947	        if (!assets.loaded()) {
948	            DrawText("Asset packs missing - run tools/fetch_assets.sh for the full look", 24,
949	                     GetScreenHeight() - 40, 18, Color{255, 225, 130, 255});
950	        }
951	        if (screenshotPath && maxFrames >= 0 && frames >= maxFrames) {
952	            TakeScreenshot(screenshotPath);
953	        }
954	        EndDrawing();
955	    }
956	
957	shutdown:
958	    // Transcripts with unsaved turns persist on quit; their summary refresh
959	    // happens at the next conversation close (summarizing here would block
960	    // shutdown on the LLM).
961	    for (std::size_t i = 0; i < world.npcs().size(); ++i) {
962	        const Npc& npc = world.npcs()[i];
963	        if (npc.history().size() > savedTurns[i]) {
964	            memoryStore.save(npc.persona().name, npc.memory(), npc.history());
965	        }
966	    }
967	
968	    leaveSession();
969	    CloseWindow();
970	    return 0;
971	}
