9	namespace {
10	
11	// Executes one parameter-less statement; true on success.
12	bool exec(sqlite3* db, const char* sql) {
13	    char* err = nullptr;
14	    if (sqlite3_exec(db, sql, nullptr, nullptr, &err) != SQLITE_OK) {
15	        std::cerr << "[llm_npc] sqlite: " << (err ? err : "unknown error") << "\n";
16	        sqlite3_free(err);
17	        return false;
18	    }
19	    return true;
20	}
21	
22	// Upserts one (character_id, value) row into `table`.`column`.
23	bool upsert(sqlite3* db, const char* table, const char* column,
24	            const std::string& characterId, const std::string& value) {
25	    if (!db) return false;
26	    const std::string sql =
27	        std::string("INSERT INTO ") + table + " (character_id, " + column +
28	        ", updated_at) VALUES (?1, ?2, datetime('now')) "
29	        "ON CONFLICT(character_id) DO UPDATE SET " +
30	        column + " = excluded." + column + ", updated_at = excluded.updated_at";
31	    sqlite3_stmt* stmt = nullptr;
32	    if (sqlite3_prepare_v2(db, sql.c_str(), -1, &stmt, nullptr) != SQLITE_OK) {
33	        std::cerr << "[llm_npc] sqlite prepare failed: " << sqlite3_errmsg(db) << "\n";
34	        return false;
35	    }
36	    sqlite3_bind_text(stmt, 1, characterId.c_str(), -1, SQLITE_TRANSIENT);
37	    sqlite3_bind_text(stmt, 2, value.c_str(), -1, SQLITE_TRANSIENT);
38	    const bool okStep = sqlite3_step(stmt) == SQLITE_DONE;
39	    if (!okStep) {
40	        std::cerr << "[llm_npc] sqlite save failed: " << sqlite3_errmsg(db) << "\n";
41	    }
42	    sqlite3_finalize(stmt);
43	    return okStep;
44	}
45	
46	// Reads one (character_id → value) cell; false when absent/unreadable.
47	bool selectOne(sqlite3* db, const char* table, const char* column,
48	               const std::string& characterId, std::string& value) {
49	    if (!db) return false;
50	    const std::string sql = std::string("SELECT ") + column + " FROM " + table +
51	                            " WHERE character_id = ?1";
52	    sqlite3_stmt* stmt = nullptr;
53	    if (sqlite3_prepare_v2(db, sql.c_str(), -1, &stmt, nullptr) != SQLITE_OK) {
54	        return false;
55	    }
56	    sqlite3_bind_text(stmt, 1, characterId.c_str(), -1, SQLITE_TRANSIENT);
57	    bool found = false;
58	    if (sqlite3_step(stmt) == SQLITE_ROW) {
59	        if (const unsigned char* s = sqlite3_column_text(stmt, 0)) {
60	            value = reinterpret_cast<const char*>(s);
61	            found = true;
62	        }
63	    }
64	    sqlite3_finalize(stmt);
65	    return found;
66	}
67	
68	}  // namespace
69	
70	CharacterStore::CharacterStore(const std::filesystem::path& dbPath) {
71	    std::error_code ec;
72	    if (dbPath.has_parent_path()) {
73	        std::filesystem::create_directories(dbPath.parent_path(), ec);  // best effort
74	    }
75	    if (sqlite3_open(dbPath.string().c_str(), &db_) != SQLITE_OK) {
76	        std::cerr << "[llm_npc] could not open " << dbPath
77	                  << " — created characters will not persist this session\n";
78	        sqlite3_close(db_);
79	        db_ = nullptr;
80	        return;
81	    }
82	    // Two independent tables joined only by character_id — persona and look
83	    // never share a row (the ticket's independence requirement, enforced by
84	    // schema rather than convention).
85	    if (!exec(db_,
86	              "CREATE TABLE IF NOT EXISTS character_persona ("
87	              "  character_id TEXT PRIMARY KEY,"
88	              "  persona_text TEXT NOT NULL DEFAULT '',"
89	              "  updated_at TEXT NOT NULL DEFAULT '')") ||
90	        !exec(db_,
91	              "CREATE TABLE IF NOT EXISTS character_look ("
92	              "  character_id TEXT PRIMARY KEY,"
93	              "  look_json TEXT NOT NULL DEFAULT '',"
94	              "  updated_at TEXT NOT NULL DEFAULT '')")) {
95	        sqlite3_close(db_);
96	        db_ = nullptr;
97	    }
98	}
99	
100	CharacterStore::~CharacterStore() {
101	    if (db_) sqlite3_close(db_);
102	}
103	
104	bool CharacterStore::savePersona(const std::string& characterId,
105	                                 const std::string& personaText) {
106	    return upsert(db_, "character_persona", "persona_text", characterId, personaText);
107	}
108	
109	bool CharacterStore::saveLook(const std::string& characterId,
110	                              const CharacterLook& look) {
111	    return upsert(db_, "character_look", "look_json", characterId, look.toJson());
112	}
113	
114	bool CharacterStore::loadPersona(const std::string& characterId,
115	                                 std::string& personaText) const {
116	    return selectOne(db_, "character_persona", "persona_text", characterId,
117	                     personaText);
118	}
119	
120	bool CharacterStore::loadLook(const std::string& characterId,
121	                              CharacterLook& look) const {
122	    std::string json;
123	    if (!selectOne(db_, "character_look", "look_json", characterId, json)) {
124	        return false;
125	    }
126	    if (!CharacterLook::fromJson(json, look)) {
127	        std::cerr << "[llm_npc] corrupt look for \"" << characterId
128	                  << "\" — skipping\n";
129	        return false;
130	    }
131	    return true;
132	}
133	
134	std::vector<StoredCharacter> CharacterStore::loadAll() const {
135	    std::vector<StoredCharacter> out;
136	    if (!db_) return out;
137	    sqlite3_stmt* stmt = nullptr;
138	    if (sqlite3_prepare_v2(db_,
139	                           "SELECT character_id FROM character_persona "
140	                           "ORDER BY character_id",
141	                           -1, &stmt, nullptr) != SQLITE_OK) {
142	        return out;
143	    }
144	    std::vector<std::string> ids;
145	    while (sqlite3_step(stmt) == SQLITE_ROW) {
146	        if (const unsigned char* s = sqlite3_column_text(stmt, 0)) {
147	            ids.emplace_back(reinterpret_cast<const char*>(s));
148	        }
149	    }
150	    sqlite3_finalize(stmt);
151	
152	    for (const std::string& id : ids) {
153	        StoredCharacter c;
154	        c.characterId = id;
155	        if (!loadPersona(id, c.personaText) || c.personaText.empty()) {
156	            std::cerr << "[llm_npc] character \"" << id
157	                      << "\" has no persona — skipping\n";
158	            continue;
159	        }
160	        if (!loadLook(id, c.look)) {
161	            std::cerr << "[llm_npc] character \"" << id
162	                      << "\" has no readable look — skipping\n";
163	            continue;
164	        }
165	        out.push_back(std::move(c));
166	    }
167	    return out;
168	}
