7	namespace llm_npc {
8	
9	namespace {
10	
11	// Tiny deterministic PRNG (xorshift32) so randomizeLook(seed) is stable
12	// across platforms — std::mt19937 would work too, but this keeps the
13	// contract obvious and header-free.
14	struct Rng {
15	    unsigned state;
16	    unsigned next() {
17	        state ^= state << 13;
18	        state ^= state >> 17;
19	        state ^= state << 5;
20	        return state;
21	    }
22	    // Uniform pick in [0, n).
23	    std::size_t pick(std::size_t n) { return n ? next() % n : 0; }
24	};
25	
26	}  // namespace
27	
28	const std::vector<CategorySpec>& categorySpecs() {
29	    // Body is the root; everything else names its parent and socket. Adding
30	    // a category (e.g. Accessory on the body's "hand" socket) is one row.
31	    static const std::vector<CategorySpec> specs = {
32	        {PartCategory::Body, PartCategory::Body, ""},
33	        {PartCategory::Head, PartCategory::Body, "head"},
34	        {PartCategory::Eyes, PartCategory::Head, "eyes"},
35	        {PartCategory::Hair, PartCategory::Head, "hair"},
36	    };
37	    return specs;
38	}
39	
40	const std::vector<PartDef>& partCatalog() {
41	    // All positions are in each part's own local space, anchor at
42	    // bottom-center. Two style families plus "any" parts; sockets are
43	    // authored per part — a wider head simply declares its eye socket
44	    // farther forward, and every eye part inherits that for free.
45	    static const std::vector<PartDef> parts = {
46	        // Bodies (declare where a head sits on THEM).
47	        {"body_round", PartCategory::Body, "round", {0.90f, 1.00f, 0.52f},
48	         {{"head", {0.f, 0.98f, 0.f}}}},
49	        {"body_block", PartCategory::Body, "blocky", {0.84f, 1.00f, 0.46f},
50	         {{"head", {0.f, 1.00f, 0.f}}}},
51	        // Heads (declare where eyes and hair sit on THEM).
52	        {"head_round", PartCategory::Head, "round", {0.72f, 0.72f, 0.72f},
53	         {{"eyes", {0.f, 0.40f, 0.30f}}, {"hair", {0.f, 0.64f, 0.f}}}},
54	        {"head_block", PartCategory::Head, "blocky", {0.76f, 0.76f, 0.76f},
55	         {{"eyes", {0.f, 0.44f, 0.38f}}, {"hair", {0.f, 0.72f, 0.f}}}},
56	        // Eyes.
57	        {"eyes_dot", PartCategory::Eyes, "any", {0.34f, 0.10f, 0.08f}, {}},
58	        {"eyes_wide", PartCategory::Eyes, "round", {0.46f, 0.16f, 0.08f}, {}},
59	        {"eyes_visor", PartCategory::Eyes, "blocky", {0.58f, 0.14f, 0.08f}, {}},
60	        // Hair. "hair_none" is a real part with zero size so the assembly
61	        // never has holes and the picker has an explicit bald option.
62	        {"hair_none", PartCategory::Hair, "any", {0.f, 0.f, 0.f}, {}},
63	        {"hair_tuft", PartCategory::Hair, "round", {0.30f, 0.26f, 0.30f}, {}},
64	        {"hair_bowl", PartCategory::Hair, "any", {0.76f, 0.28f, 0.76f}, {}},
65	        {"hair_spikes", PartCategory::Hair, "blocky", {0.70f, 0.30f, 0.70f}, {}},
66	    };
67	    return parts;
68	}
69	
70	const std::vector<PartPalette>& paletteCatalog() {
71	    static const std::vector<PartPalette> palettes = {
72	        {"warm", {236, 188, 150}, {92, 60, 34}, {70, 120, 168}},
73	        {"cool", {224, 172, 138}, {36, 32, 30}, {96, 78, 140}},
74	        {"sunny", {242, 200, 160}, {214, 172, 60}, {188, 84, 60}},
75	        {"forest", {208, 158, 122}, {70, 46, 28}, {74, 128, 82}},
76	        {"mono", {228, 214, 198}, {150, 150, 158}, {64, 66, 74}},
77	    };
78	    return palettes;
79	}
80	
81	const PartDef* findPart(const std::string& id) {
82	    for (const PartDef& part : partCatalog()) {
83	        if (part.id == id) return &part;
84	    }
85	    return nullptr;
86	}
87	
88	bool styleCompatible(const PartDef& a, const PartDef& b) {
89	    return a.styleTag == "any" || b.styleTag == "any" || a.styleTag == b.styleTag;
90	}
91	
92	std::vector<const PartDef*> partsForCategory(PartCategory category,
93	                                             const std::string& styleTag) {
94	    std::vector<const PartDef*> out;
95	    for (const PartDef& part : partCatalog()) {
96	        if (part.category != category) continue;
97	        if (styleTag == "any" || part.styleTag == "any" || part.styleTag == styleTag) {
98	            out.push_back(&part);
99	        }
100	    }
101	    return out;
102	}
103	
104	bool lookIsValid(const CharacterLook& look, std::string* why) {
105	    const PartDef* chosen[kPartCategoryCount] = {};
106	    for (int c = 0; c < kPartCategoryCount; ++c) {
107	        const std::string& id = look.partIds[c];
108	        if (id.empty()) {
109	            if (why) *why = "missing part for a category";
110	            return false;
111	        }
112	        chosen[c] = findPart(id);
113	        if (!chosen[c]) {
114	            if (why) *why = "unknown part: " + id;
115	            return false;
116	        }
117	        if (chosen[c]->category != static_cast<PartCategory>(c)) {
118	            if (why) *why = id + " is in the wrong category slot";
119	            return false;
120	        }
121	    }
122	    for (int a = 0; a < kPartCategoryCount; ++a) {
123	        for (int b = a + 1; b < kPartCategoryCount; ++b) {
124	            if (!styleCompatible(*chosen[a], *chosen[b])) {
125	                if (why) {
126	                    *why = chosen[a]->id + " and " + chosen[b]->id +
127	                           " mix incompatible styles";
128	                }
129	                return false;
130	            }
131	        }
132	    }
133	    bool paletteKnown = false;
134	    for (const PartPalette& palette : paletteCatalog()) {
135	        paletteKnown = paletteKnown || palette.id == look.paletteId;
136	    }
137	    if (!paletteKnown) {
138	        if (why) *why = "unknown palette: " + look.paletteId;
139	        return false;
140	    }
141	    return true;
142	}
143	
144	AssembledLook assembleLook(const CharacterLook& look) {
145	    AssembledLook out;
146	    if (!lookIsValid(look, &out.error)) return out;
147	
148	    // Resolve category anchors in spec order (parents listed before
149	    // children), each child at parent anchor + parent's declared socket.
150	    Vec3 anchors[kPartCategoryCount];
151	    for (const CategorySpec& spec : categorySpecs()) {
152	        const int c = static_cast<int>(spec.category);
153	        const PartDef* part = findPart(look.partIds[c]);
154	        if (spec.socket[0] == '\0') {
155	            anchors[c] = Vec3{};  // root sits on the ground at the origin
156	        } else {
157	            const int p = static_cast<int>(spec.parent);
158	            const PartDef* parent = findPart(look.partIds[p]);
159	            const auto socket = parent->sockets.find(spec.socket);
160	            if (socket == parent->sockets.end()) {
161	                out.error = parent->id + " has no '" + spec.socket + "' socket";
162	                return out;
163	            }
164	            anchors[c] = anchors[p] + socket->second;
165	        }
166	        out.parts.push_back({part, anchors[c]});
167	        out.height = std::max(out.height, anchors[c].y + part->localSize.y);
168	    }
169	    out.ok = out.height > 0.f;
170	    if (!out.ok) out.error = "assembled look has no height";
171	    return out;
172	}
173	
174	CharacterLook randomizeLook(unsigned seed) {
175	    Rng rng{seed ? seed : 1u};  // xorshift can't start at 0
176	    CharacterLook look;
177	
178	    // Body first — it sets the style family the other picks must match.
179	    const auto bodies = partsForCategory(PartCategory::Body, "any");
180	    const PartDef* body = bodies[rng.pick(bodies.size())];
181	    look.part(PartCategory::Body) = body->id;
182	    for (const CategorySpec& spec : categorySpecs()) {
183	        if (spec.category == PartCategory::Body) continue;
184	        const auto options = partsForCategory(spec.category, body->styleTag);
185	        look.part(spec.category) = options[rng.pick(options.size())]->id;
186	    }
187	    const auto& palettes = paletteCatalog();
188	    look.paletteId = palettes[rng.pick(palettes.size())].id;
189	    return look;
190	}
191	
192	std::string CharacterLook::toJson() const {
193	    nlohmann::json j;
194	    j["body"] = part(PartCategory::Body);
195	    j["head"] = part(PartCategory::Head);
196	    j["eyes"] = part(PartCategory::Eyes);
197	    j["hair"] = part(PartCategory::Hair);
198	    j["palette"] = paletteId;
199	    return j.dump();
200	}
201	
202	bool CharacterLook::fromJson(const std::string& json, CharacterLook& out) {
203	    const nlohmann::json j = nlohmann::json::parse(json, nullptr, false);
204	    if (!j.is_object()) return false;
205	    const char* keys[kPartCategoryCount] = {"body", "head", "eyes", "hair"};
206	    for (int c = 0; c < kPartCategoryCount; ++c) {
207	        if (!j.contains(keys[c]) || !j[keys[c]].is_string()) return false;
208	        out.partIds[c] = j[keys[c]].get<std::string>();
209	    }
210	    if (!j.contains("palette") || !j["palette"].is_string()) return false;
211	    out.paletteId = j["palette"].get<std::string>();
212	    return true;
213	}
214	
215	}  // namespace llm_npc
