168	MenuResult Menu::update(float dt) {
169	    if (toastLeft_ > 0.f) {
170	        toastLeft_ -= dt;
171	        if (toastLeft_ <= 0.f) toast_.clear();
172	    }
173	
174	    // Armed key capture eats the keyboard until a key lands or Escape.
175	    if (awaiting_) {
176	        if (IsKeyPressed(KEY_ESCAPE)) {
177	            awaiting_.reset();
178	            showToast("Rebind cancelled");
179	            return MenuResult::None;
180	        }
181	        const int key = GetKeyPressed();
182	        if (key != 0) applyCapture(key);
183	        return MenuResult::None;
184	    }
185	
186	    // Creator field editing: typed characters go into the focused field.
187	    if (editingField_ != 0) {
188	        std::string& field = editingField_ == 1   ? creatorName_
189	                             : editingField_ == 2 ? creatorBackstory_
190	                                                  : creatorTraits_;
191	        const std::size_t cap = editingField_ == 1 ? 32 : 160;
192	        int ch = GetCharPressed();
193	        while (ch != 0) {
194	            if (ch >= 32 && ch < 127 && field.size() < cap) {
195	                field.push_back(static_cast<char>(ch));
196	            }
197	            ch = GetCharPressed();
198	        }
199	        if ((IsKeyPressed(KEY_BACKSPACE) || IsKeyPressedRepeat(KEY_BACKSPACE)) &&
200	            !field.empty()) {
201	            field.pop_back();
202	        }
203	        if (IsKeyPressed(KEY_ESCAPE) || IsKeyPressed(KEY_ENTER)) {
204	            editingField_ = 0;
205	            return MenuResult::None;  // the Escape ends the edit, not the page
206	        }
207	        // Clicking elsewhere also drops focus (fall through to clicks).
208	    }
209	
210	    // Address editing: typed characters go into the field.
211	    if (editingAddress_) {
212	        int ch = GetCharPressed();
213	        while (ch != 0) {
214	            if (ch >= 32 && ch < 127 && joinAddress_.size() < 64) {
215	                joinAddress_.push_back(static_cast<char>(ch));
216	            }
217	            ch = GetCharPressed();
218	        }
219	        if ((IsKeyPressed(KEY_BACKSPACE) || IsKeyPressedRepeat(KEY_BACKSPACE)) &&
220	            !joinAddress_.empty()) {
221	            joinAddress_.pop_back();
222	        }
223	        if (IsKeyPressed(KEY_ESCAPE)) editingAddress_ = false;
224	        if (IsKeyPressed(KEY_ENTER)) {
225	            editingAddress_ = false;
226	            attemptJoin();
227	        }
228	        // Clicking empty space also drops focus (fall through to clicks).
229	    }
230	
231	    if (!editingAddress_ && IsKeyPressed(KEY_ESCAPE)) {
232	        if (page_ != Page::Main) {
233	            page_ = Page::Main;
234	            return MenuResult::None;
235	        }
236	        return MenuResult::Resume;
237	    }
238	
239	    if (IsMouseButtonPressed(MOUSE_BUTTON_LEFT)) {
240	        const Vector2 click = GetMousePosition();
241	        bool hitSomething = false;
242	        for (const Hit& hit : layout()) {
243	            if (!CheckCollisionPointRec(click, hit.rect)) continue;
244	            hitSomething = true;
245	            if (hit.id == kIdResume) return MenuResult::Resume;
246	            if (hit.id == kIdQuit) return MenuResult::Quit;
247	            if (hit.id == kIdControls) {
248	                page_ = Page::Controls;
249	            } else if (hit.id == kIdMultiplayer) {
250	                page_ = Page::Multiplayer;
251	                editingAddress_ = false;
252	            } else if (hit.id == kIdCreator) {
253	                page_ = Page::Creator;
254	                editingField_ = 0;
255	            } else if (hit.id == kIdBack) {
256	                awaiting_.reset();
257	                editingAddress_ = false;
258	                editingField_ = 0;
259	                page_ = Page::Main;
260	            } else if (hit.id >= kIdFieldBase + 1 && hit.id <= kIdFieldBase + 3) {
261	                editingField_ = hit.id - kIdFieldBase;
262	            } else if (hit.id >= kIdPartPrev && hit.id < kIdPartPrev + kPartCategoryCount) {
263	                editingField_ = 0;
264	                cycleCreatorPart(static_cast<PartCategory>(hit.id - kIdPartPrev), -1);
265	            } else if (hit.id >= kIdPartNext && hit.id < kIdPartNext + kPartCategoryCount) {
266	                editingField_ = 0;
267	                cycleCreatorPart(static_cast<PartCategory>(hit.id - kIdPartNext), +1);
268	            } else if (hit.id == kIdPalette) {
269	                editingField_ = 0;
270	                const auto& palettes = paletteCatalog();
271	                std::size_t index = 0;
272	                for (std::size_t i = 0; i < palettes.size(); ++i) {
273	                    if (palettes[i].id == draftLook_.paletteId) index = i;
274	                }
275	                draftLook_.paletteId = palettes[(index + 1) % palettes.size()].id;
276	            } else if (hit.id == kIdRandomize) {
277	                editingField_ = 0;
278	                creatorSeed_ = creatorSeed_ * 7919u + 13u;
279	                draftLook_ = randomizeLook(creatorSeed_);
280	            } else if (hit.id == kIdCreate) {
281	                editingField_ = 0;
282	                attemptCreate();
283	            } else if (hit.id == kIdHost) {
284	                if (multiplayer_.onHost) {
285	                    const std::string error = multiplayer_.onHost(kDefaultHostPort);
286	                    showToast(error.empty() ? "Hosting started" : error);
287	                }
288	            } else if (hit.id == kIdAddress) {
289	                editingAddress_ = true;
290	            } else if (hit.id == kIdJoin) {
291	                editingAddress_ = false;
292	                attemptJoin();
293	            } else if (hit.id == kIdLeave) {
294	                if (multiplayer_.onLeave) multiplayer_.onLeave();
295	                showToast("Left the session");
296	            } else if (hit.id >= kIdChipBase &&
297	                       hit.id < kIdChipBase + static_cast<int>(kActionCount)) {
298	                awaiting_ = static_cast<Action>(hit.id - kIdChipBase);
299	                toast_.clear();
300	            }
301	            break;
302	        }
303	        // Clicking empty space cancels an armed capture or field edit.
304	        if (!hitSomething) {
305	            awaiting_.reset();
306	            editingAddress_ = false;
307	            editingField_ = 0;
308	        }
309	    }
310	
311	    return MenuResult::None;
312	}
