314	void Menu::applyCapture(int key) {
315	    const std::string name = keyNameOf(key);
316	    if (name.empty()) {
317	        showToast("That key can't be bound");
318	        return;
319	    }
320	    const Action action = *awaiting_;
321	    awaiting_.reset();
322	    const std::optional<Action> displaced = bindings_.rebind(action, name);
323	    if (displaced) {
324	        showToast(std::string("Swapped keys with \"") + KeyBindings::actionLabel(*displaced) +
325	                  "\"");
326	    } else {
327	        showToast(std::string(KeyBindings::actionLabel(action)) + " is now " + name);
328	    }
329	    if (!bindings_.save(savePath_)) {
330	        showToast("Warning: could not save key bindings");
331	    }
