334	void Menu::cycleCreatorPart(PartCategory category, int direction) {
335	    // Options are gated by the BODY's style family (the body is the style
336	    // anchor); cycling the body itself offers every body, then re-validates
337	    // the other categories against the new family.
338	    const PartDef* body = findPart(draftLook_.part(PartCategory::Body));
339	    const std::string gate =
340	        category == PartCategory::Body ? "any" : (body ? body->styleTag : "any");
341	    const auto options = partsForCategory(category, gate);
342	    if (options.empty()) return;
343	
344	    std::size_t index = 0;
345	    for (std::size_t i = 0; i < options.size(); ++i) {
346	        if (options[i]->id == draftLook_.part(category)) index = i;
347	    }
348	    index = (index + options.size() + static_cast<std::size_t>(direction)) %
349	            options.size();
350	    draftLook_.part(category) = options[index]->id;
351	
352	    if (category == PartCategory::Body) {
353	        const PartDef* newBody = options[index];
354	        for (const CategorySpec& spec : categorySpecs()) {
355	            if (spec.category == PartCategory::Body) continue;
356	            const PartDef* current = findPart(draftLook_.part(spec.category));
357	            if (current && styleCompatible(*newBody, *current)) continue;
358	            const auto valid = partsForCategory(spec.category, newBody->styleTag);
359	            if (!valid.empty()) draftLook_.part(spec.category) = valid.front()->id;
360	        }
361	    }
362	}
