364	void Menu::attemptCreate() {
365	    if (!creator_.onCreate) return;
366	    if (trim(creatorName_).empty()) {
367	        showToast("Name required");
368	        return;
369	    }
370	    const std::string error =
371	        creator_.onCreate(trim(creatorName_), trim(creatorBackstory_),
372	                          trim(creatorTraits_), draftLook_);
373	    if (!error.empty()) {
374	        showToast(error);
375	        return;
376	    }
377	    showToast(trim(creatorName_) + " has moved into town!");
378	    creatorName_.clear();
379	    creatorBackstory_.clear();
